216	    `[ANNAHME]`: Diese Story übernimmt bewusst noch **nicht** die volle `price-summary`-Panel-Optik aus `DESIGN.md` (`background: primary-container`, sticky Box) — das ist laut `DESIGN.md`/`EXPERIENCE.md` der `price-summary`-Komponente (Story 2.4) zugeordnet, die Gesamtpreis + diese Zeilen gemeinsam in einem Panel zeigt. Diese Story liefert nur die Zeilen-Logik/-Struktur innerhalb des bereits in Story 2.1 reservierten `.booking__summary`-Slots; Story 2.4 kapselt sie visuell in `price-summary`, ohne diese Komponente umbenennen zu müssen (`PriceCategoryList` bleibt die Preiskategorie-Zeilen-Komponente, `price-summary`-Panel kommt als umgebender Container hinzu).
217	  - [ ] `features/booking/price-category-list/price-category-list.spec.ts` (neu, Vitest, `TestBed.createComponent`-Pattern mit echtem `BookingSelectionService` als Provider — kein Mock nötig, da der Test denselben Vertrag prüft, den `SeatMapGrid` bereits nutzt):
218	    ```typescript
219	    import { TestBed } from '@angular/core/testing';
220	
221	    import { PriceCategoryList } from './price-category-list';
222	    import { BookingSelectionService } from '../booking-selection.service';
223	    import { PriceCategory } from '../../../core/api/event-detail';
224	
225	    describe('PriceCategoryList', () => {
226	      const categories: PriceCategory[] = [
227	        { id: 10, name: 'Kategorie A', preis: 25 },
228	        { id: 20, name: 'Kategorie B', preis: 45 }
229	      ];
230	
231	      function createFixture() {
232	        TestBed.configureTestingModule({
233	          imports: [PriceCategoryList],
234	          providers: [BookingSelectionService]
235	        });
236	        const fixture = TestBed.createComponent(PriceCategoryList);
237	        fixture.componentRef.setInput('priceCategories', categories);
238	        const selection = TestBed.inject(BookingSelectionService);
239	        return { fixture, selection };
240	      }
241	
242	      it('zeigt einen Hinweistext ohne ausgewählte Sitzplätze, kein <select>', () => {
243	        const { fixture } = createFixture();
244	        fixture.detectChanges();
245	
246	        const root = fixture.nativeElement as HTMLElement;
247	        expect(root.querySelector('select')).toBeNull();
248	        expect(root.textContent).toContain('Wählen Sie Sitzplätze');
249	      });
250	
251	      it('zeigt für jeden ausgewählten Sitzplatz eine eigene Preiskategorie-Zeile mit allen Kategorien', () => {
252	        const { fixture, selection } = createFixture();
253	        selection.toggle('B', 3);
254	        fixture.detectChanges();
255	
256	        const root = fixture.nativeElement as HTMLElement;
257	        expect(root.textContent).toContain('Sitzplatz B3');
258	        const options = root.querySelectorAll('select option');
259	        expect(options.length).toBe(3); // "Bitte wählen" + 2 Kategorien
260	        expect(root.textContent).toContain('Kategorie A – 25,00 €');
261	      });
262	
263	      it('ordnet einem Sitzplatz per Auswahl im <select> eine Preiskategorie zu, ohne andere zu verändern', () => {
264	        const { fixture, selection } = createFixture();
265	        selection.toggle('A', 1);
266	        selection.toggle('C', 5);
267	        fixture.detectChanges();
268	
269	        const selects = fixture.nativeElement.querySelectorAll('select');
270	        selects[0].value = '10';
271	        selects[0].dispatchEvent(new Event('change'));
272	
273	        expect(selection.selectedSeats()).toEqual([
274	          { rowLabel: 'A', columnNumber: 1, priceCategoryId: 10 },
275	          { rowLabel: 'C', columnNumber: 5, priceCategoryId: null }
276	        ]);
277	      });
278	
279	      it('entfernt die Zeile eines Sitzplatzes, sobald er im Service abgewählt wird', () => {
280	        const { fixture, selection } = createFixture();
281	        selection.toggle('A', 1);
282	        fixture.detectChanges();
283	        expect(fixture.nativeElement.querySelectorAll('select').length).toBe(1);
284	
285	        selection.toggle('A', 1);
